import bpy, math, numpy as np
from mathutils import Vector

views = {
 0: ([3.7038,-6.4158,2.6786],[-0.4851,0.8403,-0.2419],[-0.1209,0.2095,0.9703]),
 3: ([-4.5185,7.8271,4.1211],[0.4698,-0.8138,-0.342],[0.171,-0.2962,0.9397]),
 4: ([-9.3321,0.0,3.1582],[0.9703,0.0,-0.2419],[0.2419,0.0,0.9703]),
}
half = math.tan(math.radians(19.8))
def cam_frame(i):
    pos,d,up = views[i]
    f=Vector(d).normalized(); u=Vector(up).normalized()
    r=f.cross(u).normalized(); u2=r.cross(f)
    return Vector(pos), r, u2, f
def project(i,P):
    pos,r,u,f=cam_frame(i)
    v=Vector(P)-pos; x,y,z=v.dot(r),v.dot(u),v.dot(f)
    if z<=0: return None
    return (384+(x/(z*half))*384, 384+(y/(z*half))*384, z)

def masks(i):
    img=bpy.data.images[f'render_000{i}.png']
    n=len(img.pixels[:])//4
    a=np.array(img.pixels[:]).reshape(n,4)[:,:3].reshape(768,768,3)
    r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
    lum=a.mean(axis=2)
    walnut=(r<0.55)&(r>g*1.25)&(g>b*1.05)&(r>0.08)
    blue=(b>r*1.12)&(b>0.15)
    black=(lum<0.22)
    silver=(lum>0.40)&(lum<0.80)&(np.abs(r-g)<0.04)&(np.abs(g-b)<0.04)
    beige=(r>0.45)&(r<0.75)&(np.abs(r-g)<0.12)&(r>b*1.15)
    return dict(a=a,walnut=walnut,blue=blue,black=black,silver=silver,beige=beige,lum=lum)
def bbox(m):
    ys,xs=np.nonzero(m)
    if len(xs)==0: return None
    return xs.min(),xs.max(),ys.min(),ys.max(),len(xs)

for i in (0,3,4):
