    print(f"--- view{i}")
    for k in ('walnut','blue','black','silver','beige'):
        print(f"  {k}: {bbox(m[k])}")

# where my pieces project in view3 & view0
def pb(i,cx,cy,sx,sy,z0,z1):
    xs=[];ys=[]
    for dx in (-sx/2,sx/2):
        for dy in (-sy/2,sy/2):
            for z in (z0,z1):
                p=project(i,(cx+dx,cy+dy,z))
                if p: xs.append(p[0]); ys.append(p[1])
    return (round(min(xs)),round(max(xs)),round(min(ys)),round(max(ys)))
